"""Convert between integers 1..3999 and canonical upper-case Roman numerals."""

_PAIRS = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def to_roman(n):
    """Return the standard upper-case numeral for n, which must be 1 to 3999."""
    if not isinstance(n, int) or isinstance(n, bool) or not 1 <= n <= 3999:
        raise ValueError(f"expected an integer from 1 to 3999, got {n!r}")
    out = []
    for value, numeral in _PAIRS:
        count, n = divmod(n, value)
        out.append(numeral * count)
    return "".join(out)


def from_roman(s):
    """Return the integer for a canonical numeral such as "MCMXCIV"."""
    if not isinstance(s, str) or not s:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    total = 0
    for i, ch in enumerate(s):
        if ch not in _VALUES:
            raise ValueError(f"not a canonical Roman numeral: {s!r}")
        value = _VALUES[ch]
        nxt = _VALUES.get(s[i + 1]) if i + 1 < len(s) else 0
        total += -value if value < nxt else value
    # Only the exact string to_roman produces is accepted, which rejects
    # forms such as "IIII", "IC", "VX" and "mcm".
    if total < 1 or total > 3999 or to_roman(total) != s:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    return total

